public class Main {
    enum Level { LOW, MEDIUM, HIGH }

    public static void main(String[] args) {
        Level level = Level.valueOf("HIGH");
        if (level == Level.HIGH) {
            System.out.println("Alert!");
        } else {
            System.out.println("Fine");
        }
    }
}
